tay unvalued. To remove expired or damaged stock, select the batch in <a href="/losses" wire:navigate>Stock Losses</a>.</p></section>
<details class="panel ledger-details"><summary>Batch movement history</summary><p class="muted">All batch movements. Original sale and return records keep their allocation snapshots. Discarded returns create a zero-stock movement because the goods already left stock at sale.</p><div class="table-wrap"><table><thead><tr><th>Date</th><th>Product / batch</th><th>Source / reference</th><th>Unit change</th><th>Remaining before → after</th></tr></thead><tbody>@forelse($batchMovements as $movement)<tr><td>{{ \Illuminate\Support\Carbon::parse($movement['time'])->setTimezone('Asia/Shanghai')->format('M j · g:i A') }}</td><td class="wrappable">{{ $overview['batches'][$movement['batchId']]['name'] ?? 'Product' }}<br><button wire:click="inspectBatch('{{ $movement['batchId'] }}')">{{ substr($movement['batchId'],0,8) }}</button></td><td class="wrappable">{{ $movement['source'] }}<br>{{ $movement['reference'] }}</td><td>{{ $movement['quantity']>0 ? '+' : '' }}{{ $movement['quantity'] }}</td><td>{{ $movement['before'] }} → {{ $movement['after'] }}</td></tr>@empty<tr><td colspan="5">No batch movements recorded yet.</td></tr>@endforelse</tbody></table></div></details>
